(function(xhr) {
  try {
    var urlToMonitorText = atob('TDJGd2FTOW5jbUZ3YUhGc0x3PT0=') // palavra /api/graphql/
    var sponsoredText = atob('VTFCUFRsTlBVa1ZF') // palavra SPONSORED

    urlToMonitorText = atob(urlToMonitorText)
    sponsoredText = atob(sponsoredText)

    var XHR = Object.getPrototypeOf(new XMLHttpRequest)
    var open = Object.getPrototypeOf(new XMLHttpRequest).open;
    var send = Object.getPrototypeOf(new XMLHttpRequest).send;
    // var setRequestHeader = XHR.setRequestHeader;
    var setRequestHeader = Object.getPrototypeOf(new XMLHttpRequest).setRequestHeader;

    XHR.open = function (method, url) {
      this._method = method;
      this._url = url;
      this._requestHeaders = {};
      this._startTime = (new Date()).toISOString();

      return open.apply(this, arguments);
    };

    XHR.setRequestHeader = function (header, value) {
      this._requestHeaders[header] = value;
      return setRequestHeader.apply(this, arguments);
    };
    let arrDs = []
    XHR.send = function (postData) {
      try {
        this.addEventListener('load', function () {
          var myUrl = this._url ? this._url.toLowerCase() : this._url;
          if (myUrl && myUrl === urlToMonitorText) {

            if (postData) {
              if (typeof postData === 'string') {
                try {
                  this._requestHeaders = postData;
                } catch (err) {

                }
              } else if (typeof postData === 'object' || typeof postData === 'array' || typeof postData === 'number' || typeof postData === 'boolean') {}
            }
            if (this.responseType != 'blob' && this.responseText) {
              try {
                var arr = this.responseText;
                var datas = arr.split('\n');
                datas.forEach((data, i) => {
                  data = JSON.parse(data)
                  // arrDs.push(data)
                  // console.log(arrDs)
                  if (data?.data?.ad_library_main ||
                    (data?.label?.includes('AdLibraryMobileFocusedStateProvider') &&
                      data?.data?.ad_library_main)) {
                        window.postMessage({
                          type: 'LIBRARY_AD_DATA',
                          data: data
                        }, "*");
                  }
                  if (data.data.viewer && data.data.viewer.news_feed) {
                    data.data.viewer.news_feed.edges.forEach((edge, i) => {
                      if (edge?.node?.sponsored_data || edge?.node.daspo_sto) {
                        window.postMessage({
                          type: "ADS",
                          payload: edge
                        }, "*");
                      }
                    });
                  } else if (data?.data?.br_sf_cnt === null && data?.data?.node?.comet_sections) {
                    window.postMessage({
                      type: "ADS",
                      payload: data.data
                    }, "*");
                  } else if (data?.data?.category === 'SPONSORED' || data?.data?.category === 'sponsored') {
                    window.postMessage({
                      type: "ADS SPONSORED",
                      payload: data.data
                    }, "*");
                  } else if (data?.data?.sponsored_auction_distance) {
                    window.postMessage({
                      type: "ADS SPONSORED",
                      payload: data.data
                    }, "*");
                  }
                })

              } catch (err) {
                window.postMessage({
                  type: "error",
                  payload: this.responseText
                }, "*");
              }
            }
          }
        })
        return send.apply(this, arguments);
      } catch (e) {

      }
    }

    Element.prototype._removeChild = Element.prototype.removeChild;
    Element.prototype.removeChild = function (child) {
      try {
        if(child && child.className){
          var elementClass = child.className;
          if (elementClass.indexOf('d8enrfuj36') > -1) {
            return child;
          }
        }
      } catch (error) {};

      return Element.prototype._removeChild.apply(this, arguments);
    }

  } catch (error) {

  }

})(XMLHttpRequest);